function currentDevice(){const ua=navigator.userAgent||'',ios=/iPhone|iPad|iPod/i.test(ua),android=/Android/i.test(ua),tablet=/iPad|Tablet/i.test(ua)||(android&&!/Mobile/i.test(ua)),platform=ios?'iOS':android?'Android':'PC',deviceType=tablet?'tablet':ios||android?'mobile':'desktop',browser=/Edg\//i.test(ua)?'Microsoft Edge':/Firefox\//i.test(ua)?'Firefox':/CriOS|Chrome\//i.test(ua)?'Google Chrome':/Safari\//i.test(ua)?'Safari':'Navegador';return{terminalId,platform,deviceType,browser,userAgent:ua,channel:appMode==='standalone-pos'?'PDV':'ERP'}}
async function syncCurrentDevice(isLogin=false){if(!authSession)return null;try{const record=await FloralisBackend.registerDevice?.(currentDevice(),isLogin);if(canAdmin()&&isLogin){state.devices=FloralisBackend.isRemote()?await FloralisBackend.loadDevices():[record];save()}return record}catch(error){if(isLogin)toast(error,'error');return null}}
function auditEvent(action,module,details='',level='info'){if(!authSession)return;const entry={id:globalThis.crypto?.randomUUID?.()||`LOG-${Date.now()}-${Math.random().toString(16).slice(2)}`,date:new Date().toISOString(),userId:authSession.userId,user:authSession.name,email:authSession.email,role:authSession.role,module,action,details,level,terminalId,channel:appMode==='standalone-pos'?'PDV':'ERP',userAgent:navigator.userAgent};state.auditLogs.unshift(entry);state.auditLogs=state.auditLogs.slice(0,2000);save();FloralisBackend.recordAudit?.(entry).catch(()=>{})}
const locale=()=>state.settings.language==='pt'?'pt-BR':'es-BO';
const currencies={BOB:{code:'BOB',symbol:'Bs',name:'Boliviano',locale:'es-BO'},BRL:{code:'BRL',symbol:'R$',name:'Real brasileiro',locale:'pt-BR'},USD:{code:'USD',symbol:'$',name:'Dólar',locale:'en-US'}};
const currencyId=value=>Object.hasOwn(currencies,String(value||''))?String(value):'BOB';
const exchangeRate=code=>Math.max(.000001,Number(state.settings.exchangeRates?.[currencyId(code)])||1);
const convertMoney=(value,code)=>Number(value||0)*exchangeRate(code);
const baseMoney=(value,code)=>Number(value||0)/exchangeRate(code);
const moneyIn=(value,code=state.settings.baseCurrency||'BOB')=>{const selected=currencies[currencyId(code)];return`${selected.symbol} ${convertMoney(value,selected.code).toLocaleString(selected.locale,{minimumFractionDigits:2,maximumFractionDigits:2})}`};
const money=v=>moneyIn(v,state.settings.baseCurrency||'BOB');
const posMoney=v=>moneyIn(v,ui.posCurrency||state.settings.baseCurrency||'BOB');
const date=v=>new Intl.DateTimeFormat(locale(),{day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(v));
const time=v=>new Intl.DateTimeFormat(locale(),{hour:'2-digit',minute:'2-digit'}).format(new Date(v));
const initials=n=>n.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const sum=(arr,k='amount')=>arr.reduce((n,x)=>n+Number(x[k]||0),0);
const avatar=(p,n,cls='')=>`<span class="avatar ${cls}" ${p?`style="background-image:url('${esc(p)}');color:transparent"`:''}>${initials(n)}</span>`;
