function loadFontAssets(id){const font=fontThemes[fontId(id)];if(!font.google)return;const href=`https://fonts.googleapis.com/css2?family=${font.google}&display=swap`;if(document.querySelector(`link[data-app-font="${fontId(id)}"]`)||document.querySelector(`link[href="${href}"]`))return;const link=document.createElement('link');link.rel='stylesheet';link.href=href;link.dataset.appFont=fontId(id);document.head.appendChild(link)}
function applyFont(id){const chosen=fontId(id);loadFontAssets(chosen);document.documentElement.dataset.font=chosen;document.documentElement.style.setProperty('--app-font',fontThemes[chosen].stack)}
