function appErrorInfo(error){const raw=String(error?.message||error||'').trim();if(/^[A-Z]{3}-\d{3}\s+—/.test(raw))return{code:raw.split(/\s+/)[0],reason:raw.replace(/^[A-Z]{3}-\d{3}\s+—\s*/,''),solution:''};const item=errorCatalog.find(entry=>entry.match.test(raw))||errorCatalog.at(-1),copy=state.settings.language==='pt'?item.pt:item.es;return{...item,reason:copy[0],solution:copy[1]}}
function formatAppError(error){const info=appErrorInfo(error);return`${info.code} — ${info.reason}`}
