function translateText(value){if(state.settings.language!=='pt')return value;const lead=value.match(/^\s*/)?.[0]||'',trail=value.match(/\s*$/)?.[0]||'',core=value.trim();if(!core)return value;if(ptText[core])return lead+ptText[core]+trail;return lead+core.replace(/^Mostrando /,'Mostrando ').replace(/ transacciones$/,' movimentações').replace(/^Cantidad: /,'Quantidade: ').replace(/ artículo(s)?$/,' item$1').replace(/^Hecho por /,'Atendido por ').replace(/^Período: /,'Período: ').replace(/^Pago: /,'Pagamento: ')+trail}
function applyLanguageDOM(root=document){document.documentElement.lang=state.settings.language==='pt'?'pt-BR':'es';if(state.settings.language!=='pt')return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>{if(!['SCRIPT','STYLE'].includes(node.parentElement?.tagName))node.nodeValue=translateText(node.nodeValue)});$$('input[placeholder],textarea[placeholder]',root).forEach(el=>{el.placeholder=translateText(el.placeholder)});$$('[title]',root).forEach(el=>{el.title=translateText(el.title)});$$('[aria-label]',root).forEach(el=>{el.setAttribute('aria-label',translateText(el.getAttribute('aria-label')))})}
function languageSelector(compact=false){return `<label class="language-switch ${compact?'compact':''}" title="Idioma"><span>${svg('globe')}</span><select data-language aria-label="Idioma"><option value="es" ${state.settings.language!=='pt'?'selected':''}>ES</option><option value="pt" ${state.settings.language==='pt'?'selected':''}>PT</option></select></label>`}
function applyBrand(){
 const appearance=state.settings.appearance||{},mode=appearance.mode||'light',resolved=mode==='auto'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):mode,accent=palettes[appearance.palette]||appearance.accent||state.settings.accent||'#3b82f6';
 document.documentElement.dataset.theme=resolved;document.documentElement.dataset.palette=appearance.palette||'blue';document.documentElement.dataset.shell=appearance.shell||'nex';document.documentElement.dataset.scale=['small','medium','large'].includes(appearance.scale)?appearance.scale:'medium';applyFont(appearance.font);document.documentElement.style.setProperty('--accent',accent);document.documentElement.style.setProperty('--accent-rgb',hexRgb(accent));
 const logo=String(state.settings.logo||'');document.documentElement.style.setProperty('--brand-logo',logo?`url("${logo.replace(/"/g,'\\"')}")`:'none');document.documentElement.style.setProperty('--brand-watermark-opacity',String(Math.min(.12,Math.max(.015,Number(state.settings.watermarkOpacity)||.045))));
 document.querySelector('meta[name="theme-color"]')?.setAttribute('content',accent);document.title=`${state.settings.businessName} — ${appMode==='standalone-pos'?'Terminal PDV':'PDV & ERP'}`;
 const mini=$('#miniBrand');if(mini)mini.innerHTML=logo?`<img src="${esc(logo)}" alt="${esc(state.settings.businessName||'Empresa')}">`:esc((state.settings.businessName||'G')[0]);if(logo)$$('link[rel="icon"],link[rel="apple-touch-icon"]').forEach(link=>{link.href=logo});applyLanguageDOM(document);
}
function hexRgb(hex){const value=String(hex).replace('#','');if(value.length!==6)return'0,152,249';return`${parseInt(value.slice(0,2),16)},${parseInt(value.slice(2,4),16)},${parseInt(value.slice(4,6),16)}`}
const canAdmin=()=>authSession?.role==='admin';
const currentEmployee=()=>state.employees.find(x=>x.id===authSession?.userId)||state.employees.find(x=>x.email===authSession?.email)||(canAdmin()?null:state.employees[0]);
const allowedViews=()=>canAdmin()?['sales','clients','products','stock','catalog','cash','reports','documents','employees','devices','logs','tutorial','settings']:['sales','clients','products','stock','cash','reports','documents','tutorial','settings'];

function companyBadge(){return `<span class="company-badge">${state.settings.logo?`<img src="${esc(state.settings.logo)}" alt="Logo ${esc(state.settings.businessName)}">`:`<i>${esc((state.settings.businessName||'G')[0])}</i>`}<span><small>Sistema de</small><strong>${esc(state.settings.businessName||'Empresa')}</strong></span></span>`}
function pageHeader(title,count='',settings=false){const initial=initials(authSession?.name||'Usuario').slice(0,1);return `<header class="page-header"><button class="mobile-menu-button" data-action="toggle-mobile-menu" aria-label="Abrir menú">${svg('menu')}</button><h1 class="page-title">${esc(title)}</h1>${count!==''?`<span class="page-count">(${count})</span>`:''}<span class="header-spacer"></span>${companyBadge()}${languageSelector(true)}<a class="plan-button" href="./pdv.html" target="_blank">Abrir terminal PDV ${svg('monitor')}</a><button class="user-button" data-action="user-menu" title="${esc(authSession?.name||'Usuario')}">${initial}</button>${settings&&canAdmin()?`<button class="header-settings" data-action="open-quick-settings">${svg('settings')}</button>`:''}</header>`}
function empty(icon,title,text){return `<div class="empty-state"><span class="empty-icon">${svg(icon)}</span><h3>${title}</h3><p>${text}</p></div>`}
function search(value,placeholder,id='pageSearch'){return `<div class="search-field"><span class="search-icon">${svg('search')}</span><input id="${id}" value="${esc(value)}" placeholder="${esc(placeholder)}" autocomplete="off"/><span class="shortcut">Ctrl+F</span></div>`}
function tabs(items,current,attr){return `<div class="tabs">${items.map(([id,label,disabled])=>`<button class="tab ${current===id?'active':''}" data-${attr}="${id}" ${disabled?'disabled':''}>${label}</button>`).join('')}</div>`}

function setView(view){if(!allowedViews().includes(view))view='sales';ui.view=view;ui.search='';ui.menu=false;$('#sidebar')?.classList.remove('open');sessionStorage.setItem('floralis.lastView',view);history.replaceState(null,'',`${location.pathname}#${view}`);$$('.menu-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));render();$('#app')?.focus({preventScroll:true});if(view==='devices'&&canAdmin())setTimeout(refreshDevices,80);if(view!=='tutorial'&&!ui.tutorialTopic)setTimeout(()=>{if(authSession&&!$('#guidedTutorial')&&$('#layer')?.hidden)showFirstTutorial()},350)}
function render(){if(!authSession)return renderLogin();const map={sales:renderSales,clients:renderClients,products:renderProducts,stock:renderStock,catalog:renderCatalog,cash:renderCash,reports:renderReports,documents:()=>FloralesDocuments.render(),employees:renderEmployees,devices:renderDevices,logs:renderLogs,tutorial:renderTutorialCenter,settings:renderSettings};if(!allowedViews().includes(ui.view))ui.view='sales';$('#app').innerHTML=map[ui.view]();injectIcons($('#app'));syncNavigation();applyLanguageDOM(document)}
function syncNavigation(){const shell=$('.nex-shell');if(shell)shell.hidden=false;$$('.menu-item[data-view]').forEach(button=>{button.hidden=!allowedViews().includes(button.dataset.view);button.classList.toggle('active',button.dataset.view===ui.view)})}
function renderLogin(message=''){
 document.body.classList.add('auth-mode');const shell=$('.nex-shell');if(shell)shell.hidden=false;
 const demo=window.FLORALIS_CONFIG?.mode!=='supabase',errorMessage=message?formatAppError(message):'';$('#app').innerHTML=`<section class="login-page"><div class="login-language">${languageSelector()}</div><div class="login-visual"><div class="login-brand"><img src="./assets/floralis-logo.png" alt="Florales — Más que flores... emociones."></div><div><p class="eyebrow">PDV + ERP PARA FLORES E PRESENTES</p><h1>Venda com carinho.<br>Organize com facilidade.</h1><p>Terminal rápido para buquês, flores e presentes, com estoque, entregas, clientes e caixa no mesmo lugar.</p></div><small>Más que flores... emociones. · BOB · BRL · USD</small></div><div class="login-panel"><form id="loginForm" class="login-card"><div class="mobile-logo"><img src="./assets/floralis-mark.png" alt="Florales"></div><p class="eyebrow">ACCESO SEGURO</p><h2>${appMode==='standalone-pos'?'Abrir terminal PDV':'Iniciar sesión'}</h2><p class="login-copy">Use el acceso asignado por el administrador.</p>${errorMessage?`<div class="login-error">${esc(errorMessage)}</div>`:''}<div class="field"><label>Correo electrónico</label><input name="email" type="email" autocomplete="username" required placeholder="nombre@empresa.com"></div><div class="field"><label>Contraseña</label><input name="password" type="password" autocomplete="current-password" required placeholder="••••••••"></div><button class="btn primary login-submit" type="submit">${appMode==='standalone-pos'?'Entrar y abrir caja':'Entrar al sistema'}</button>${demo?`<div class="demo-access"><strong>Accesos de demostración</strong><button type="button" data-demo-login="admin">Administrador · admin@example.invalid</button><button type="button" data-demo-login="employee">Funcionario · employee@example.invalid</button><small>Contraseñas: admin123 / func123</small></div>`:''}<span class="login-security">La sesión permanece abierta en este dispositivo hasta cerrar sesión.</span></form></div></section>`;injectIcons($('#app'));applyLanguageDOM(document)
}
async function startAuthenticated(session){authSession=session;document.body.classList.remove('auth-mode');try{if(canAdmin())await FloralisBackend.ensureTrainingProduct?.();const workspace=await FloralisBackend.loadWorkspace();if(workspace){const pending=(state.sales||[]).filter(s=>s.syncStatus==='pending'&&state.offlineQueue.some(q=>q.clientSaleId===s.clientSaleId)),pendingDocuments=(state.generatedDocuments||[]).filter(item=>item.syncStatus==='pending');state={...state,...workspace,sales:[...pending,...workspace.sales.filter(s=>!pending.some(p=>p.clientSaleId===s.clientSaleId))],generatedDocuments:[...pendingDocuments,...(workspace.generatedDocuments||[]).filter(item=>!pendingDocuments.some(p=>p.clientDocumentId===item.clientDocumentId))],settings:{...state.settings,...workspace.settings,appearance:{...state.settings.appearance,...workspace.settings.appearance},posLayout:{...state.settings.posLayout,...workspace.settings.posLayout},cashClosing:{...state.settings.cashClosing,...workspace.settings.cashClosing}}};save()}}catch(error){toast(`No fue posible sincronizar: ${error.message}`,'error')}syncCurrentDevice(true);auditEvent('Inicio de sesión','Autenticación',`${appMode==='standalone-pos'?'Terminal PDV':'Panel ERP'} · ${terminalId}`,'success');checkAutomaticCashClose();ensureCashSession();if(appMode==='standalone-pos')openPos();else{const hash=location.hash.slice(1);setView(allowedViews().includes(hash)?hash:ui.view)}setTimeout(()=>session.mustChangePassword?credentialForm(true):showFirstTutorial(),250)}
function userMenu(){const head=appMode==='standalone-pos'?`<header class="layer-head"><h1>Mi sesión</h1><button class="layer-close" data-action="back-pos">${svg('close')}</button></header>`:layerHead('Mi sesión');openLayer(`${head}<div class="layer-body"><div class="profile-head">${avatar('',authSession.name)}<div><h3>${esc(authSession.name)}</h3><p>${canAdmin()?'Administrador':'Funcionario'} · ${esc(authSession.email)}</p></div></div><div class="session-actions">${appMode==='standalone-pos'?`<a class="btn primary" href="./index.html#sales">${svg('monitor')} Volver al panel ERP</a>`:''}<button class="btn" data-action="open-help">Ayuda y tutorial</button><button class="btn" data-action="cycle-theme">Cambiar modo visual</button><button class="btn danger" data-action="logout">Cerrar sesión</button></div></div>`,'modal narrow')}
function credentialForm(required=false){const session=FloralisBackend.getSession?.()||authSession;openLayer(`${required?'<header class="layer-head"><h1>Proteja su acceso</h1></header>':layerHead('Mi acceso')}<form id="${required?'mandatoryCredentialsForm':'accountCredentialsForm'}"><div class="layer-body"><div class="access-security-hero">${svg('settings')}<div><strong>${required?'Cree una nueva contraseña para continuar':'Credenciales del administrador'}</strong><span>${required?'La contraseña temporal debe ser reemplazada en el primer acceso.':'Cambie el correo o la contraseña sin exponerlos en el banco del ERP.'}</span></div></div><div class="form-grid"><div class="field full"><label>Correo de acceso</label><input name="email" type="email" value="${esc(session?.email||'')}" autocomplete="email" required></div><div class="field"><label>Nueva contraseña</label><input name="password" type="password" minlength="8" autocomplete="new-password" ${required?'required':''} placeholder="Mínimo 8 caracteres"></div><div class="field"><label>Confirmar contraseña</label><input name="confirmPassword" type="password" minlength="8" autocomplete="new-password" ${required?'required':''}></div></div><div class="form-warning">Use una contraseña exclusiva. Ninguna contraseña se guarda en las tablas del ERP.</div></div><footer class="layer-foot">${required?'':`<button type="button" class="btn" data-action="${appMode==='standalone-pos'?'back-pos':'close-layer'}">Cancelar</button>`}<button class="btn primary" type="submit">Guardar credenciales</button></footer></form>`,'modal narrow access-modal')}
function visibleSales(){if(canAdmin())return state.sales;const employee=currentEmployee();return state.sales.filter(s=>s.employeeId===authSession?.userId||s.employee===employee?.name||s.employee===authSession?.name)}
function byPeriod(rows,label){if(label==='Todo el historial')return rows;if(label==='Este mes'){const now=new Date();return rows.filter(x=>{const d=new Date(x.date);return d.getMonth()===now.getMonth()&&d.getFullYear()===now.getFullYear()})}const days=parseInt(label)||7,limit=Date.now()-days*86400000;return rows.filter(x=>new Date(x.date).getTime()>=limit)}

function renderSales(){
 const tabType={history:'Venta',orders:'Pedido',budgets:'Presupuesto'}[ui.salesTab]||'Venta';
 const rows=byPeriod(visibleSales(),ui.salesPeriod).filter(s=>(s.type||'Venta')===tabType).filter(s=>`${s.id} ${s.client} ${s.employee} ${s.payment}`.toLowerCase().includes(ui.search.toLowerCase())).filter(s=>ui.salesPayment==='Todos'||s.payment===ui.salesPayment);
 return `<section class="page page-sales">${pageHeader('Ventas')}<div class="page-body no-top"><div class="action-bar"><button class="btn primary" data-action="open-pos">Nueva Venta - F3</button><button class="btn secondary" data-action="new-order">Nuevo Pedido</button><button class="btn secondary" data-action="new-budget">Nuevo Presupuesto</button></div>${tabs([['history','Historial'],['orders','Pedidos abiertos'],['accept','Pedidos por aceptar',true],['budgets','Presupuestos']],ui.salesTab,'sales-tab')}<div class="toolbar" style="margin-top:16px">${search(ui.search,'Buscar por número, cliente o vendedor')}<button class="filter-chip" data-action="cycle-sales-payment">${svg('filter')} Pago: ${esc(ui.salesPayment)}</button><button class="filter-chip" data-action="cycle-sales-period">${esc(ui.salesPeriod)} ${svg('down')}</button><span class="grow"></span><span class="filter-chip">Mostrando ${rows.length}</span></div>
 <div class="data-region"><table class="data-table"><thead><tr><th>Acción</th><th>Número</th><th>Resumen</th><th>Tipo</th><th>Fecha</th><th>Hora</th><th>Ítems</th><th>Cliente</th><th>Vendedor</th><th>Subtotal</th><th>Valor pagado</th><th>Pago</th></tr></thead><tbody>${rows.map(s=>`<tr><td><button class="table-action" data-sale-view="${s.id}">Ver</button></td><td>${esc(s.id)}</td><td>${esc(s.items)} productos</td><td>${esc(s.type)}</td><td>${date(s.date)}</td><td>${time(s.date)}</td><td>${s.items}</td><td>${esc(s.client)}</td><td>${esc(s.employee)}</td><td>${moneyIn(s.total,s.currency||state.settings.baseCurrency)}</td><td><strong>${moneyIn(s.total,s.currency||state.settings.baseCurrency)}</strong></td><td>${esc(s.payment)}</td></tr>`).join('')}</tbody></table>${rows.length?'':empty('receipt','Sin transacciones registradas','Sus ventas aparecerán aquí.') }<div class="summary-row"><span>${rows.length} transacciones</span><span>Total <strong>${money(sum(rows,'total'))}</strong></span></div></div></div></section>`
}

function renderClients(){
 const sorter={Nombre:(a,b)=>a.name.localeCompare(b.name),Saldo:(a,b)=>a.balance-b.balance,Compras:(a,b)=>b.purchases-a.purchases}[ui.clientSort];const rows=state.clients.filter(c=>`${c.name} ${c.document} ${c.phone} ${c.code}`.toLowerCase().includes(ui.search.toLowerCase())).filter(c=>ui.clientFilter==='Todos'||ui.clientFilter==='Con deuda'&&c.balance<0||ui.clientFilter==='Con crédito'&&c.balance>0).sort(sorter);
 return `<section class="page page-clients">${pageHeader('Clientes',state.clients.length)}<div class="page-body"><div class="toolbar"><button class="btn circle" data-action="client-new" title="Nuevo cliente">${svg('plus')}</button>${search(ui.search,'Buscar por nombre, documento o teléfono')}<button class="filter-chip" data-action="cycle-client-sort" title="Cambiar orden">${svg('down')} ${esc(ui.clientSort)}</button><button class="filter-chip" data-action="cycle-client-filter">${svg('filter')} ${esc(ui.clientFilter)}</button></div><div class="data-region"><table class="data-table"><thead><tr><th>Acción</th><th>Nombre</th><th>Débito / Crédito</th><th>Estado</th><th>Código</th><th>Observación</th><th>Nacimiento</th><th>CI / NIT</th><th>Ciudad</th><th>Celular</th><th>Tipo</th></tr></thead><tbody>${rows.map(c=>`<tr data-client-row="${c.id}" title="Clic derecho para pagar deuda, imprimir o corregir el saldo"><td class="client-row-actions"><button class="table-action" data-client-view="${c.id}">Ver cuenta</button><button class="table-action row-menu" data-client-menu="${c.id}" title="Más opciones" aria-label="Más opciones de ${esc(c.name)}">${svg('dots')}</button></td><td><div class="item-cell">${avatar(c.photo,c.name)}<div><strong>${esc(c.name)}</strong><small>${esc(c.document)}</small></div></div></td><td class="${c.balance<0?'money-negative':'money-positive'}">${c.balance<0?'− ':c.balance>0?'+ ':''}${money(Math.abs(c.balance))}</td><td><span class="status ${c.balance<0?'danger':''}">${c.balance<0?'Con deuda':c.balance>0?'Con crédito':'Activo'}</span></td><td>${esc(c.code)}</td><td>${esc(c.notes||'—')}</td><td>${birthdateCell(c)}</td><td>${esc(c.document)}</td><td>${esc(c.city)}</td><td>${esc(c.phone)}</td><td>${esc(c.type)}</td></tr>`).join('')}</tbody></table>${rows.length?'':empty('users','Ningún cliente encontrado','No hay clientes que correspondan a la búsqueda.')}</div></div></section>`
}

function renderProducts(){
 const cats=['Todas',...new Set(state.products.map(p=>p.category))];
 const sorter={Nombre:(a,b)=>a.name.localeCompare(b.name),Stock:(a,b)=>a.stock-b.stock,Precio:(a,b)=>a.price-b.price}[ui.productSort];const rows=state.products.filter(p=>(ui.productCategory==='Todas'||p.category===ui.productCategory)&&`${p.name} ${p.code} ${p.ean}`.toLowerCase().includes(ui.search.toLowerCase())).filter(p=>ui.productFilter==='Todos'||ui.productFilter==='Stock bajo'&&p.stock<=p.minStock||ui.productFilter==='Sin stock'&&p.stock===0).sort(sorter);
 const toolbar=`<div class="toolbar">${canAdmin()?`<button class="btn circle" data-action="product-new" title="Nuevo producto">${svg('plus')}</button>`:''}${search(ui.search,'Buscar por código, EAN/GTIN o nombre')}<button class="filter-chip" data-action="cycle-product-sort">${svg('down')} ${esc(ui.productSort)}</button><button class="filter-chip" data-action="cycle-product-filter">${svg('filter')} ${esc(ui.productFilter)}</button><button class="btn circle" data-action="open-quick-settings" title="Configuración rápida">${svg('menu')}</button></div>`;
 let content='';
 if(ui.productTab==='labels')content=`${toolbar}<div class="label-action-bar"><div><strong>Etiquetas de precio</strong><span>${rows.length} productos listos para imprimir</span></div><button class="btn primary" data-action="print-labels">${svg('receipt')} Imprimir etiquetas</button></div><div class="product-label-grid">${rows.map(p=>`<article class="product-label"><small>${esc(state.settings.businessName)}</small><strong>${esc(p.name)}</strong><span>${esc(p.code||p.ean||'Sin código')}</span><b>${money(p.price)}</b><em>${esc(p.unit||'Unidad')}</em></article>`).join('')||empty('tag','Sin etiquetas','Registre productos para generar etiquetas de precio.')}</div>`;
 else if(ui.productTab==='suppliers')content=`${toolbar}<div class="data-region"><table class="data-table"><thead><tr><th>Acción</th><th>Producto</th><th>Proveedor</th><th>Código proveedor</th><th>Último costo</th><th>Contacto / nota</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${canAdmin()?`<button class="table-action" data-product-edit="${p.id}">Editar</button>`:'Consultar'}</td><td><strong>${esc(p.name)}</strong><small>${esc(p.code)}</small></td><td>${esc(p.supplier||'Sin proveedor')}</td><td>${esc(p.supplierCode||'—')}</td><td>${money(p.lastCost??p.cost)}</td><td>${esc(p.supplierNote||'—')}</td></tr>`).join('')}</tbody></table>${rows.length?'':empty('store','Sin proveedores','Asigne un proveedor desde la ficha de cada producto.')}</div>`;
 else content=`${toolbar}<div class="products-layout"><aside class="category-panel">${cats.map(c=>`<button class="${ui.productCategory===c?'active':''}" data-category="${esc(c)}">${esc(c)} (${state.products.filter(p=>c==='Todas'||p.category===c).length})</button>`).join('')}${canAdmin()?'<button class="manage" data-action="manage-categories">Gestionar categorías</button>':''}</aside><div class="data-region"><table class="data-table"><thead><tr><th>Acción</th><th>Imagen</th><th>Nombre</th><th>Código</th><th>Precio de venta</th><th>Precio mayorista</th><th>Stock actual</th><th>Costo</th><th>Categoría</th><th>Unidad</th><th>EAN/GTIN</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${canAdmin()?`<button class="table-action" data-product-edit="${p.id}">Editar</button>`:'Consultar'}</td><td>${productThumb(p)}</td><td><strong>${esc(p.name)}</strong></td><td>${esc(p.code)}</td><td><strong>${money(p.price)}</strong></td><td>${money(p.wholesale)}</td><td><span class="status ${p.stock===0?'danger':p.stock<=p.minStock?'warning':''}">${p.stock}</span></td><td>${money(p.cost)}</td><td>${esc(p.category)}</td><td>${esc(p.unit)}</td><td>${esc(p.ean)}</td></tr>`).join('')}</tbody></table>${rows.length?'':empty('box','Sin productos','Registre su primer producto para comenzar.')}</div></div>`;
 return `<section class="page page-products">${pageHeader('Productos',state.products.length,true)}${tabs([['items','Artículos'],['labels','Etiquetas'],['suppliers','Proveedores']],ui.productTab,'product-tab')}<div class="page-body">${content}</div></section>`
}

function renderStock(){
 const rows=state.products.filter(p=>`${p.name} ${p.code}`.toLowerCase().includes(ui.search.toLowerCase())).filter(p=>ui.stockFilter==='Todos'||ui.stockFilter==='Stock bajo'&&p.stock<=p.minStock||ui.stockFilter==='Sin stock'&&p.stock===0);
 const toolbar=`<div class="toolbar">${search(ui.search,'Buscar por nombre o código del producto')}<button class="filter-chip" data-action="cycle-stock-filter">${svg('filter')} ${esc(ui.stockFilter)}</button><button class="btn circle" data-action="inventory-summary" title="Valor del inventario">${svg('cash')}</button></div>`;
 if(ui.stockTab==='transactions'){const movements=(state.stockMovements||[]).filter(m=>{const p=state.products.find(x=>x.id===m.productId);return`${p?.name||''} ${p?.code||''} ${m.reason||''}`.toLowerCase().includes(ui.search.toLowerCase())});return `<section class="page page-stock">${pageHeader('Inventario')}${tabs([['stock','Stock por producto'],['transactions','Transacciones']],ui.stockTab,'stock-tab')}<div class="page-body">${toolbar}<div class="data-region"><table class="data-table"><thead><tr><th>Fecha</th><th>Producto</th><th>Tipo</th><th>Cantidad</th><th>Motivo</th><th>Funcionario</th></tr></thead><tbody>${movements.map(m=>{const p=state.products.find(x=>x.id===m.productId),label=m.type==='in'?'Entrada':m.type==='out'?'Salida':'Corrección';return`<tr><td>${date(m.date)} · ${time(m.date)}</td><td><strong>${esc(p?.name||'Producto eliminado')}</strong></td><td><span class="status ${m.type==='out'?'danger':m.type==='set'?'warning':''}">${label}</span></td><td class="${m.type==='out'?'money-negative':'money-positive'}">${m.type==='out'?'−':'+'} ${Number(m.amount).toLocaleString(locale())}</td><td>${esc(m.reason||'—')}</td><td>${esc(m.employee||'—')}</td></tr>`}).join('')}</tbody></table>${movements.length?'':empty('box','Sin transacciones','Los movimientos de entrada, salida y corrección aparecerán aquí.')}</div></div></section>`}
 return `<section class="page page-stock">${pageHeader('Inventario')}${tabs([['stock','Stock por producto'],['transactions','Transacciones']],ui.stockTab,'stock-tab')}<div class="page-body">${toolbar}<div class="data-region"><table class="data-table"><thead><tr><th>Acción</th><th>Producto</th><th>Stock actual</th><th>Reservado</th><th>Disponible</th><th>Categoría</th><th>Precio</th><th>Unidad</th><th>Código</th><th>Estado</th></tr></thead><tbody>${rows.map(p=>`<tr><td><button class="table-action" data-stock-move="${p.id}">Movimiento</button></td><td><div class="item-cell">${productThumb(p)}<strong>${esc(p.name)}</strong></div></td><td class="stock-number">${p.stock.toFixed(3)}</td><td>0,000</td><td class="stock-number">${p.stock.toFixed(3)}</td><td>${esc(p.category)}</td><td>${money(p.price)}</td><td>${esc(p.unit)}</td><td>${esc(p.code)}</td><td><span class="status ${p.stock===0?'danger':p.stock<=p.minStock?'warning':''}">${p.stock===0?'Sin stock':p.stock<=p.minStock?'Bajo':'Disponible'}</span></td></tr>`).join('')}</tbody></table>${rows.length?'':empty('box','Sin productos','Registre productos para controlar el inventario.')}<div class="summary-row"><span>Valor de costo <strong>${money(sum(state.products.map(p=>({amount:p.stock*p.cost}))))}</strong></span><span>Valor de venta <strong>${money(sum(state.products.map(p=>({amount:p.stock*p.price}))))}</strong></span></div></div></div></section>`
}

function renderCatalog(){return `<section class="page">${pageHeader('Catálogo Online')}<div class="catalog-banner"><div class="catalog-copy"><h2>Su canal de ventas online</h2><p>Publique productos, comparta el catálogo por WhatsApp y reciba pedidos directamente en el sistema. Los precios pueden mostrarse para venta minorista o mayorista.</p><button class="btn primary" data-action="catalog-config">Configurar catálogo</button></div><div class="catalog-preview"><div class="phone-card"><div class="mini-brand">${esc(state.settings.businessName)}</div><div class="mini-products"><span></span><span></span><span></span><span></span><span></span><span></span></div></div></div></div></section>`}

function renderCash(){
 const ins=sum(state.cash.filter(m=>m.type==='in')),outs=sum(state.cash.filter(m=>m.type==='out'));
 const open=state.cashSession?.status==='open',rows=state.cash.filter(m=>ui.cashFilter==='Todos'||ui.cashFilter==='Entradas'&&m.type==='in'||ui.cashFilter==='Salidas'&&m.type==='out');return `<section class="page page-cash">${pageHeader('Caja')}<div class="page-body"><div class="cash-session-banner ${open?'open':'closed'}"><div><span>${open?'Caja abierta':'Caja cerrada'}</span><strong>${open?`Abierta por ${esc(state.cashSession.openedBy||'Usuario')} · ${date(state.cashSession.openedAt)} ${time(state.cashSession.openedAt)}`:'Abra una nueva sesión para registrar movimientos'}</strong></div>${open?`<button class="btn secondary" data-action="cash-close">Cerrar caja</button>`:`<button class="btn primary" data-action="cash-open">Abrir caja</button>`}</div><div class="action-bar"><button class="btn primary" data-action="cash-new" ${open?'':'disabled'}>Nueva transacción</button><button class="btn secondary" data-doc-cash-closing>${svg('receipt')} Informe de cierre</button><span class="grow"></span><button class="filter-chip" data-action="cycle-cash-filter">${svg('filter')} ${esc(ui.cashFilter)}</button></div><div class="metrics"><div class="metric"><span>Saldo inicial</span><strong>${money(0)}</strong></div><div class="metric"><span>Entradas</span><strong class="money-positive">${money(ins)}</strong></div><div class="metric"><span>Salidas</span><strong class="money-negative">${money(outs)}</strong></div><div class="metric"><span>Saldo esperado</span><strong>${money(ins-outs)}</strong></div></div><div class="data-region"><table class="data-table"><thead><tr><th>Acción</th><th>Fecha</th><th>Hora</th><th>Tipo</th><th>Descripción</th><th>Funcionario</th><th>Entrada</th><th>Salida</th></tr></thead><tbody>${rows.map(m=>`<tr><td><button class="table-action" data-cash-view="${m.id}">Ver</button></td><td>${date(m.date)}</td><td>${time(m.date)}</td><td><span class="status ${m.type==='out'?'danger':''}">${m.type==='in'?'Entrada':'Salida'}</span></td><td>${esc(m.description)}</td><td>${esc(m.employee)}</td><td class="money-positive">${m.type==='in'?money(m.amount):'—'}</td><td class="money-negative">${m.type==='out'?money(m.amount):'—'}</td></tr>`).join('')}</tbody></table>${rows.length?'':empty('wallet','Sin movimientos','La caja todavía no tiene entradas ni salidas.')}<div class="summary-row"><span>Movimientos ${rows.length}</span><span>Saldo <strong>${money(ins-outs)}</strong></span></div></div></div></section>`
}

const reportCatalog={
 general:{label:'Resumen rápido',items:['Resumen','Rentabilidad','Ingresos / gastos']},
 sales:{label:'Ventas',items:['Entradas por moneda','Medios de pago','Por producto','Por vendedor']},
 inventory:{label:'Estoque',items:['Stock bajo','Valor del inventario']},
 cash:{label:'Caja',items:['Movimientos de caja','Cierres anteriores']}
};
const reportDescriptions={
 'Resumen':'Panorama de ventas, resultado y desempeño diario.','Entradas por moneda':'Cobros separados en bolivianos, reales y dólares según la moneda elegida en cada venta.','Rentabilidad':'Ingresos, costos y margen estimado por producto.','Ingresos / gastos':'Entradas y salidas registradas en caja.','Medios de pago':'Participación, cantidad y ticket de cada forma de pago.','Por vendedor':'Ventas y ticket promedio por funcionario.','Por producto':'Cantidad, facturación y utilidad por producto.','Horario pico':'Horarios con mayor movimiento de ventas.','Ticket promedio':'Evolución diaria del valor promedio por compra.','Ranking de ventas':'Clientes ordenados por valor comprado.','Compras por cliente':'Histórico consolidado de compras y última compra.','Movimiento de stock':'Entradas, salidas y correcciones de inventario.','Stock bajo':'Productos que llegaron al mínimo o están agotados.','Valor del inventario':'Capital inmovilizado y potencial de venta por categoría.','Movimientos de caja':'Extracto de entradas y salidas del período.','Cierres anteriores':'Histórico de cierres manuales y automáticos.','Por vencer':'Cuentas aún abiertas, ordenadas por vencimiento.','Pagadas':'Histórico de cuentas liquidadas.'
};
function reportGroupRows(rows,keyFn){const grouped=new Map();rows.forEach(row=>{const key=keyFn(row)||'Sin identificar';if(!grouped.has(key))grouped.set(key,[]);grouped.get(key).push(row)});return grouped}
function reportKpis(items){return `<div class="metrics report-metrics">${items.map(item=>`<div class="metric"><span>${esc(item[0])}</span><strong class="${item[3]||''}">${item[1]}</strong>${item[2]?`<small>${esc(item[2])}</small>`:''}</div>`).join('')}</div>`}
function reportTable(headers,rows,icon='chart',title='Sin datos para este período',description='Cambie el período o registre nuevos movimientos.'){return `<div class="data-region report-data"><table class="data-table"><thead><tr>${headers.map(header=>`<th>${esc(header)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table>${rows.length?'':empty(icon,title,description)}</div>`}
function reportBars(title,labels,values,format='money'){const peak=Math.max(...values,0);return `<div class="chart-panel report-chart"><div class="report-chart-head"><h3>${esc(title)}</h3><small>${values.some(Boolean)?'Comparación visual del período':'Sin movimientos en el período'}</small></div><div class="bars">${values.map((value,index)=>`<div class="bar" style="height:${peak?Math.max(3,Math.round(value/peak*100)):0}%" title="${format==='money'?money(value):Number(value).toLocaleString(locale())}"><b>${format==='money'?money(value):Number(value).toLocaleString(locale())}</b><span>${esc(labels[index])}</span></div>`).join('')}</div></div>`}
function reportProductRows(sales){const grouped=new Map();sales.forEach(sale=>(sale.receiptItems||[]).forEach(item=>{const product=state.products.find(p=>p.id===(item.productId||item.id)||p.code===item.code),key=item.productId||item.id||item.code||item.name,current=grouped.get(key)||{name:item.name||product?.name||'Producto',code:item.code||product?.code||'—',qty:0,revenue:0,cost:0};const qty=Number(item.qty??item.quantity??0),revenue=Number(item.total??(Number(item.unitPrice??item.price??0)*qty)),cost=Number(product?.cost||0)*qty;current.qty+=qty;current.revenue+=revenue;current.cost+=cost;grouped.set(key,current)}));return [...grouped.values()].sort((a,b)=>b.revenue-a.revenue)}
const saleReportCurrency=sale=>currencyId(sale.currency||state.settings.baseCurrency||'BOB');
const saleOriginalAmount=sale=>{const stored=Number(sale.displayTotal);return Number.isFinite(stored)&&stored>=0?stored:convertMoney(Number(sale.total||0),saleReportCurrency(sale))};
