function ledgerForm(id,type){const c=state.clients.find(x=>x.id===id);if(!c)return;const config={debit:['Añadir débito','Valor de la deuda','Compra fiada, ajuste o cargo'],credit:['Añadir crédito','Valor a favor','Crédito, devolución o anticipo'],payment:['Registrar pago','Valor recibido','Pago de deuda'],adjust:['Corregir saldo','Nuevo saldo final','Corrección manual de saldo']}[type]||['Movimiento','Valor','Movimiento'];openLayer(`${layerHead(config[0])}<form id="ledgerForm" data-id="${id}" data-type="${type}"><div class="layer-body"><div class="movement-client">${avatar(c.photo,c.name)}<div><strong>${esc(c.name)}</strong><small>Saldo actual: ${c.balance<0?'− ':c.balance>0?'+ ':''}${money(Math.abs(c.balance))}</small></div></div><div class="form-grid"><div class="field"><label>${config[1]}</label><input name="amount" type="number" ${type==='adjust'?'':'min="0.01"'} step="0.01" ${type==='adjust'?`value="${c.balance}"`:''} required></div><div class="field"><label>Fecha</label><input name="date" type="date" value="${new Date().toISOString().slice(0,10)}" required></div>${type==='payment'?`<div class="field"><label>Forma de pago</label><select name="paymentMethod"><option>Efectivo</option><option>PIX</option><option>QR</option><option>Transferencia</option></select></div>`:''}<div class="field ${type==='payment'?'':'full'}"><label>Descripción</label><input name="description" value="${esc(config[2])}" required></div></div>${type==='adjust'?'<p class="form-warning">Se creará un movimiento de ajuste; ningún historial anterior será borrado.</p>':''}</div><footer class="layer-foot"><button type="button" class="btn" data-action="back-client" data-id="${id}">Cancelar</button><button class="btn primary">Guardar movimiento</button></footer></form>`,'modal narrow')}
function employeeProfile(id){const e=state.employees.find(x=>x.id===id);if(!e)return;openLayer(`${layerHead('Perfil del funcionario')}<div class="layer-body"><div class="profile-head">${avatar(e.photo,e.name)}<div><h3>${esc(e.name)}</h3><p>${esc(e.role)} · ${esc(e.document)}</p></div><div class="profile-actions"><button class="btn secondary" data-doc-employee-report="${e.id}" data-doc-return="employee-profile">${svg('receipt')} Resumen de desempeño</button><button class="btn" data-employee-edit="${e.id}">Editar</button></div></div><div class="metrics"><div class="metric"><span>Ventas</span><strong>${e.sales}</strong></div><div class="metric"><span>Facturado</span><strong>${money(e.total)}</strong></div><div class="metric"><span>Ticket promedio</span><strong>${money(e.ticket)}</strong></div><div class="metric"><span>Meta</span><strong>${e.goal}%</strong></div></div><div class="data-region"><table class="data-table"><thead><tr><th>Número</th><th>Fecha</th><th>Cliente</th><th>Pago</th><th>Total</th><th>Informe</th></tr></thead><tbody>${state.sales.filter(s=>s.employeeId===e.id||s.employee===e.name).map(s=>`<tr><td>${s.id}</td><td>${date(s.date)}</td><td>${esc(s.client)}</td><td>${esc(s.payment)}</td><td>${moneyIn(s.total,s.currency||state.settings.baseCurrency)}</td><td><button class="table-action" data-doc-sale-report="${esc(s.uuid||s.id)}">${svg('receipt')} Ver</button></td></tr>`).join('')}</tbody></table></div></div><footer class="layer-foot"><button class="btn" data-action="close-layer">Cerrar</button></footer>`,'modal')}
